#!/usr/bin/env python3
import sys, json, re, zipfile, shutil, os

TEMPLATE = "inputs/offer_letter_template.docx"
DATA = "inputs/employee_data.json"
OUT = "output/offer_letter_filled.docx"

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def fail(msg):
    sys.stderr.write("ERROR: " + msg + "\n")
    sys.exit(1)

with open(DATA, encoding="utf-8") as f:
    data = json.load(f)

PLACEHOLDER = re.compile(r"\{\{([A-Z0-9_]+)\}\}")
IF_RE = re.compile(r"\{\{IF_RELOCATION\}\}(.*?)\{\{END_IF_RELOCATION\}\}", re.DOTALL)
GOVERNOR = "RELOCATION_PACKAGE"

missing = set()

def resolve_para(text):
    """Process a single paragraph's full text. No cross-paragraph tokens."""
    # Handle conditional first (governed strictly by RELOCATION_PACKAGE)
    def cond(m):
        if GOVERNOR not in data:
            missing.add(GOVERNOR)
            return ""  # placeholder; will fail later
        keep = (data[GOVERNOR] == "Yes")
        return m.group(1) if keep else ""
    text = IF_RE.sub(cond, text)

    # Now substitute simple field placeholders.
    def rep(m):
        name = m.group(1)
        # control tokens for conditional should already be gone; if orphaned, treat as missing data concept
        if name in ("IF_RELOCATION", "END_IF_RELOCATION"):
            # orphaned conditional marker within a single paragraph scope -> leave? These are control, not data.
            return m.group(0)
        if name not in data:
            missing.add(name)
            return m.group(0)
        return str(data[name])
    return PLACEHOLDER.sub(rep, text)

def process_part(xml):
    # Operate paragraph by paragraph so tokens never cross paragraph boundaries.
    out = []
    pos = 0
    for pm in re.finditer(r"<w:p(?:\s[^>]*)?>.*?</w:p>|<w:p(?:\s[^>]*)?/>", xml, re.DOTALL):
        out.append(xml[pos:pm.start()])
        out.append(process_paragraph(pm.group(0)))
        pos = pm.end()
    out.append(xml[pos:])
    return "".join(out)

def process_paragraph(p):
    # Collect <w:t ...>text</w:t> occurrences; join their text; replace; redistribute.
    t_re = re.compile(r"(<w:t(?:\s[^>]*)?>)(.*?)(</w:t>)", re.DOTALL)
    matches = list(t_re.finditer(p))
    if not matches:
        return p
    def unesc(s):
        return s.replace("&lt;","<").replace("&gt;",">").replace("&quot;",'"').replace("&apos;","'").replace("&amp;","&")
    def esc(s):
        return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
    joined = "".join(unesc(m.group(2)) for m in matches)
    new = resolve_para(joined)
    # Put all resulting text into the first <w:t>, empty the rest, preserve xml:space to keep whitespace.
    result = []
    pos = 0
    for i, m in enumerate(matches):
        result.append(p[pos:m.start()])
        open_tag = m.group(1)
        if i == 0:
            # ensure xml:space preserve
            if "xml:space" not in open_tag:
                open_tag = open_tag[:-1] + ' xml:space="preserve">'
            result.append(open_tag + esc(new) + m.group(3))
        else:
            if "xml:space" not in open_tag:
                open_tag = open_tag[:-1] + ' xml:space="preserve">'
            result.append(open_tag + "" + m.group(3))
        pos = m.end()
    result.append(p[pos:])
    return "".join(result)

zin = zipfile.ZipFile(TEMPLATE)
parts_to_process = {"word/document.xml", "word/header1.xml", "word/footer1.xml"}

# First pass: process in memory and collect missing
processed = {}
for name in zin.namelist():
    raw = zin.read(name)
    if name in parts_to_process:
        processed[name] = process_part(raw.decode("utf-8")).encode("utf-8")
    else:
        processed[name] = raw

# Validate: governor required because conditional appears in the template.
# Check original template for conditional presence.
doc_text = zin.read("word/document.xml").decode("utf-8")
conditional_present = "{{IF_RELOCATION}}" in doc_text or "IF_RELOCATION" in doc_text
if conditional_present and GOVERNOR not in data:
    fail("Missing required field: %s" % GOVERNOR)

# Any leftover unresolved placeholders (missing data) -> fail
if missing:
    fail("Missing required field(s): %s" % ", ".join(sorted(missing)))

# Verify no residual {{...}} placeholders remain in processed parts
for name in parts_to_process:
    txt = processed[name].decode("utf-8")
    leftover = set(re.findall(r"\{\{([A-Z0-9_]+)\}\}", txt))
    if leftover:
        fail("Unresolved placeholders remain in %s: %s" % (name, ", ".join(sorted(leftover))))

os.makedirs(os.path.dirname(OUT), exist_ok=True)
with zipfile.ZipFile(OUT, "w", zipfile.ZIP_DEFLATED) as zout:
    for name in zin.namelist():
        zout.writestr(name, processed[name])

print("OK: wrote", OUT)
